INSERT INTO public.releases (version, title, notes) VALUES ('v0.6.0', 'Path Diversity Scoring', ARRAY['Added path diversity scoring to MCTS solver — tracks distinct winning paths across simulations','New unique_winning_paths and path_diversity_score columns on deals table','DDS modifier: narrow-path deals (+8 DDS), many-path deals (−5 DDS), capped ±10','Starter Pool Generator now writes path diversity data on every deal','Boost Deal Confidence recalculates path diversity and flags low-diversity Easy/Medium deals','Admin Deals table shows path_diversity_score with warning indicators for below-threshold deals','No solvable deal is ever discarded — reclassified and banked at correct tier']);